/* tests/host/tr_pose_silicon.h -- REAL keypoints read back from 2026W36-0009 over
 * SWD (the HP -> HE pose slot, tr_pslot.h), 2026-09-25, UPRIGHT 400x640
 * frame (TR_CAM_ROTATE=90, TR_CAM_MIRROR=ON), one sample every ~4-5 pose
 * frames. Generated once from the bench capture; not regenerated by a tool.
 *   tr_sil_approach: the maintainer standing, then walking TOWARD the camera
 *     (legs out of frame; the old box read it as a 4 s JUMP);
 *   tr_sil_stand: the maintainer standing still in the centre lane.
 * test_track_intent.c replays both: neither may produce a JUMP. */
